import { Router, type Request, type Response } from 'express';
import { authMiddleware } from '../auth.js';
import {
  createChat,
  findDirectChat,
  getUnreadCount,
  listChatsForUser,
  listMessages,
  listUsers,
} from '../store.js';
import type { Chat, Message, User } from '../types.js';
import { emitToChat } from '../ws.js';

type AuthedRequest = Request & { user: User };

export type ChatListItem = Chat & {
  lastMessage: Message | null;
  unreadCount: number;
};

function asAuthed(req: Request): AuthedRequest {
  return req as AuthedRequest;
}

export const chatsRouter = Router();

chatsRouter.get('/users', authMiddleware, (req: Request, res: Response) => {
  const { user } = asAuthed(req);
  const q = typeof req.query.q === 'string' ? req.query.q : '';
  res.json(listUsers({ q, excludeId: user.id }).slice(0, 20));
});

chatsRouter.get('/chats', authMiddleware, (req: Request, res: Response) => {
  const { user } = asAuthed(req);
  const chats = listChatsForUser(user.id)
    .slice()
    .sort((a, b) => (a.updatedAt < b.updatedAt ? 1 : a.updatedAt > b.updatedAt ? -1 : 0));

  const result: ChatListItem[] = chats.map((chat) => {
    const lastMessage = listMessages(chat.id, { limit: 1 })[0] ?? null;
    const unreadCount = getUnreadCount(chat.id, user.id, null);
    return { ...chat, lastMessage, unreadCount };
  });
  res.json(result);
});

chatsRouter.post('/chats', authMiddleware, (req: Request, res: Response) => {
  const { user } = asAuthed(req);
  const body = req.body as { type?: unknown; memberIds?: unknown; title?: unknown };
  const type = body.type;
  if (type !== 'direct' && type !== 'group') {
    res.status(400).json({ error: 'invalid' });
    return;
  }
  if (!Array.isArray(body.memberIds) || !body.memberIds.every((id) => typeof id === 'string')) {
    res.status(400).json({ error: 'invalid' });
    return;
  }
  const rawMemberIds = body.memberIds as string[];
  const memberIds = Array.from(new Set([user.id, ...rawMemberIds]));

  if (type === 'direct') {
    const others = memberIds.filter((id) => id !== user.id);
    if (others.length !== 1 || rawMemberIds.filter((id) => id !== user.id).length !== 1) {
      res.status(400).json({ error: 'invalid' });
      return;
    }
    const otherId = others[0]!;
    const existing = findDirectChat(user.id, otherId);
    if (existing) {
      res.status(200).json(existing);
      return;
    }
    const chat = createChat({ type: 'direct', memberIds: [user.id, otherId], title: null });
    emitToChat(chat.id, 'chat.updated', { chatId: chat.id });
    res.status(201).json(chat);
    return;
  }

  const title = body.title;
  if (typeof title !== 'string' || title.length < 1 || title.length > 64) {
    res.status(400).json({ error: 'invalid' });
    return;
  }
  if (memberIds.filter((id) => id !== user.id).length < 1) {
    res.status(400).json({ error: 'invalid' });
    return;
  }
  const chat = createChat({ type: 'group', memberIds, title });
  emitToChat(chat.id, 'chat.updated', { chatId: chat.id });
  res.status(201).json(chat);
});
